return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Iru al Kromprogramo Serĉu','Activate %s' => 'Aktivigu %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> postulas ke <strong>%2$s</strong> estu instalita kaj aktivigita. <a href="%4$s">%3$s</a>','Enter your code here' => 'Enigu vian kodon ĉi tie','Add %s' => 'Aldonu %s','Remove' => 'Forigi','Order number and receipt will be sent to this email address.' => 'Mendnumero kaj kvitanco estos senditaj al ĉi tiu retadreso.','Apartment, unit, building, floor, etc.' => 'Apartamento, unuo, konstruaĵo, etaĝo ktp.','Shipping phone' => 'Sendotelefono','Only used for shipping-related questions.' => 'Nur uzata por send-rilataj demandoj.','Single step' => 'Ununura paŝo','Click to go to the order summary' => 'Klaku por iri al la menda resumo','Cart total:' => 'Tuta ĉaro:','Proceed to %s' => 'Iru al %s','Proceed to contact' => 'Sekvu kontakti','Proceed to shipping' => 'Procedu al sendado','Proceed to billing' => 'Procedu al fakturado','Proceed to payment' => 'Procedu al pago','Shipping method' => 'Sendado metodo','Additional notes' => 'Pliaj notoj','Payment method' => 'Pagmetodo','Step %1$s of %2$s' => 'Paŝo %1$s de %2$s','Change: %s' => 'Ŝanĝo: %s','Not selected yet.' => 'Ankoraŭ ne elektita.','Same as shipping address' => 'Sama kiel senda adreso','Same as billing address' => 'Sama kiel faktura adreso','Order summary' => 'Mendo resumo','Edit cart' => 'Redaktu ĉaron','Did you mean %s?' => 'Ĉu vi volis diri %s?','Change email address to: {suggestion-value}' => 'Ŝanĝu retadreson al: {suggestion-value}','This is a required field.' => 'Ĉi tio estas postulata kampo.','This is not a valid email address.' => 'Ĉi tio ne estas valida retadreso.','This field does not match the related field value.' => 'Ĉi tiu kampo ne kongruas kun la rilata kampa valoro.','The CPF number "{cpf_number}" is invalid.' => 'La CPF-numero &quot;{cpf_number}&quot; estas malvalida.','The CNPJ number "{cnpj_number}" is invalid.' => 'La CNPJ-numero &quot;{cnpj_number}&quot; estas malvalida.','(Required)' => '(Bezonata)','Checkout Header - Desktop' => 'Checkout Header - Labortablo','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Montru fenestraĵojn sur la kasa kaplinio por grandaj ekranoj. Nur montrata se vi uzas la kasan kaplinion de la kromaĵo.','Checkout Header - Mobile' => 'Paga Kapo - Poŝtelefono','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Montru fenestraĵojn sub la kasa kaplinio por porteblaj aparatoj. Nur montrata se vi uzas la kasan kaplinion de la kromaĵo.','Checkout Sidebar' => 'Checkout Flankbreto','Display widgets on the checkout sidebar after the order summary.' => 'Montru fenestraĵojn sur la kasa flanka kolumno post la mendo-resumo.','Checkout Order Summary' => 'Elĉerpa Mendo Resumo','Display widgets inside the order summary at the checkout page.' => 'Montru fenestraĵojn en la mendo-resumo ĉe la pagpaĝo.','Checkout Below Place Order' => 'Kontrolu Sube Faru Mendon','Display widgets below the place order button at the checkout page.' => 'Montru fenestraĵojn sub la butono de mendo ĉe la pagpaĝo.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Montru fenestraĵojn sur la pagpiedo. Nur montrata se vi uzas la pagpaĝon de la kromaĵo.','Classic' => 'Klasika','Boxed' => 'Boxed','Split' => 'Split','Minimalist' => 'Minimalisto','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Fluid Checkout kaj Livera Dato kromaĵojn de CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Ni detektis, ke vi uzas la kromaĵojn Livero kaj Kolekto Dato Tempo por WooCommerce (senpaga kaj PRO) de CodeRockz. Integriĝo kun ĉi tiuj kromaĵoj estis movita al Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Ĝisdatigu al PRO','Fluid Checkout database updated successfully' => 'Fluid Checkout-datumbazo sukcese ĝisdatigita','The database changes where applied successfully.' => 'La datumbazo ŝanĝiĝas kie aplikita sukcese.','Dismiss' => 'Forĵeti','Fluid Checkout database update' => 'Fluid Checkout datumbaza ĝisdatigo','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Kelkaj ŝanĝoj al la datumbazo estas postulataj. Kiel kun ĉiu ĝisdatigo, ni rekomendas al vi <strong>fari plenan sekurkopion de via retejo antaŭ ol daŭrigi</strong> .','Update database' => 'Ĝisdatigu datumbazon','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout ne kongruas kun la aranĝo de Divi Builder checkout','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout bezonas la klasikan WooCommerce-mallongkodon-bazitan kasan formularon por funkcii. Kiam vi uzas la Divi Builder por personecigi la aspekton de la pagpaĝo, la klasikaj mallongaj kodoj estas anstataŭigitaj per kutimaj fenestraĵoj de la Divi Builder por ĉiu parto de la pagpaĝo. Ĉi tiuj kutimaj fenestraĵoj ne kongruas kun Fluid Checkout.</p><p> Bonvolu redakti vian pagpaĝon anstataŭigante la fenestraĵojn de Divi Builder per la teksta fenestraĵo enhavanta la mallongkodon <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Redaktu la pagpaĝon','Read the documentation.' => 'Legu la dokumentadon.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanigita PRO plurpaŝa kasa funkcio devas esti malŝaltita kiam vi uzas Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Kiam vi uzas Fluid Checkout, la plurpaŝa funkcio de la Germanized PRO kromaĵo fariĝas nenecesa kaj povas kaŭzi <strong>kritikajn erarojn dum prilaborado de novaj mendoj</strong> . Bonvolu malŝalti la Germanigitan PRO-plurpaŝan pagfunkcion en la aldonaĵagordoj.','Go to Germanized settings' => 'Iru al germanigitaj agordoj','Thanks for choosing Fluid Checkout!' => 'Dankon pro la elekto de Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Vi uzas la kromprogramon dum iom da tempo. Kiel vi ŝatas ĝin ĝis nun?<br> Bonvolu doni al ni rapidan takson, ni dankas ĉiun reagon kaj ĝi instigas nin daŭre plibonigi la kromprogramon :)','Rate the plugin' => 'Taksi la kromprogramon','I need help!' => 'Mi bezonas helpon!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Iuj funkcioj de WooCommerce Checkout Manager de Quadlayers eble ne funkcias kiel atendite kiam vi uzas ĝin kun Fluid Checkout. Legu <a href="%s">nian dokumentaron</a> por pliaj informoj kaj alternativaj solvoj.','Read documentation' => 'Legu dokumentadon','Don\'t show this again' => 'Ne montru ĉi tion denove','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Pli da dezajnaj ŝablonoj','Optimized cart page' => 'Optimumigita ĉarpaĝo','Optimized order received / thank you page' => 'Optimumigita mendo ricevita/dankopaĝo','Edit cart contents at checkout page' => 'Redaktu la enhavon de ĉaro ĉe la pagpaĝo','Account matching / user matching' => 'Konto kongruo / uzantkongruo','Trust symbols on the cart and thank you pages' => 'Fidu simbolojn sur la ĉaro kaj dankon-paĝojn','More positions for the coupon code on the checkout page' => 'Pli da pozicioj por la kuponkodo sur la pagpaĝo','International phone numbers' => 'Internaciaj telefonnumeroj','Gift messages and packing slips' => 'Donacaj mesaĝoj kaj pakaj biletoj','Local pickup and in-store collection' => 'Loka kolektado kaj kolektado en vendejo','EU-VAT Assistant' => 'EU-VAT Asistanto','I already have it – Hide this offer' => 'Mi jam havas ĝin - Kaŝi ĉi tiun oferton','Activated' => 'Aktivigita','Address book' => 'Adreslibro','Select an image' => 'Elektu bildon','Cart layout' => 'Ĉaro aranĝo','Cart optimizations' => 'Ĉaro-optimumoj','Enable cart page optimizations' => 'Ebligu ĉarajn paĝajn optimumojn','Header and footer template' => 'Ŝablono de kaplinio kaj piedlinio','Controls whether to use the distraction free page header 